def transform(grid):
    sep = next(i for i, row in enumerate(grid) if all(v == 5 for v in row))
    upper, lower = grid[:sep], grid[sep + 1:]
    increase = {}
    for color in (2, 4):
        increase[color] = (sum(row.count(color) for row in lower)
                           - sum(row.count(color) for row in upper))
    color = 2 if increase[2] > increase[4] else 4
    return [[color, color], [color, color]]
